const DECODE: Record<string, InterestTag> = {
  'a': 'outdoor',
  'b': 'fitness',
  'c': 'food',
  'd': 'sports',
  'e': 'travel',
  'f': 'home',
  'g': 'community',
  'h': 'savings',
  'i': 'education',
  'j': 'animals',
  'k': 'civic',
};

export function lookupDomainInterests(hostname: string): InterestTag[] {
  const domain = hostname.replace(/^www\./, '');
  const coded = D[domain];
  if (!coded) return [];
  return [...coded].map(c => DECODE[c]).filter(Boolean);
}
